const express=require('express'),Database=require('better-sqlite3');const app=express(),db=new Database(process.env.DB_FILE||'app.db');db.pragma('foreign_keys=ON');db.exec(`CREATE TABLE IF NOT EXISTS members(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',priority TEXT NOT NULL DEFAULT 'medium',status TEXT NOT NULL DEFAULT 'todo',assignee_id INTEGER REFERENCES members(id),due_date TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP)`);
// Audit log is generated by SQLite triggers in the same transaction as each update.
// No-op updates are excluded and direct API access is read-only.
db.exec(`
CREATE TABLE IF NOT EXISTS tasks_status_events (
  id INTEGER PRIMARY KEY,
  entity_id INTEGER NOT NULL,
  previous_value TEXT NOT NULL,
  new_value TEXT NOT NULL,
  changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_tasks_events_entity ON tasks_status_events(entity_id,id);
CREATE TRIGGER IF NOT EXISTS audit_tasks_status
AFTER UPDATE OF status ON tasks
WHEN OLD.status IS NOT NEW.status
BEGIN
  INSERT INTO tasks_status_events(entity_id,previous_value,new_value)
  VALUES(NEW.id,OLD.status,NEW.status);
END;`);

app.disable('x-powered-by');app.use((req,res,next)=>{res.set('X-Content-Type-Options','nosniff');res.set('Referrer-Policy','no-referrer');res.set('X-Frame-Options','DENY');next()});app.use(express.json({limit:'32kb'}));app.use(express.static('public'));

const crypto = require('node:crypto');
app.use('/api', (req, res, next) => {
  if (req.path === '/health') return next();
  const required = process.env.API_TOKEN;
  if (!required && process.env.APP_ENV !== 'production') return next();
  if (!required) return res.status(503).json({error:'API authentication must be configured in production'});
  const actual = req.get('x-api-token') || '';
  const expectedBytes = Buffer.from(required, 'utf8');
  const actualBytes = Buffer.from(actual, 'utf8');
  if (expectedBytes.length !== actualBytes.length || !crypto.timingSafeEqual(expectedBytes, actualBytes)) {
    return res.status(401).json({error:'Unauthorized'});
  }
  next();
});

function validISODate(value){
 if(value===null||value===undefined||value==='')return true;
 if(typeof value!=='string'||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(value))return false;
 const date=new Date(value+'T00:00:00Z');
 return Number.isFinite(date.getTime()) && date.toISOString().slice(0,10)===value;
}
const wrap=fn=>(req,res)=>{try{res.json(fn(req))}catch(e){res.status(400).json({error:e.message})}};
app.get('/api/members',wrap(()=>db.prepare('SELECT * FROM members ORDER BY name').all()));app.post('/api/members',wrap(req=>{if(!req.body.name?.trim())throw Error('Name required');return db.prepare('INSERT INTO members(name) VALUES(?)').run(req.body.name.trim())}));
app.get('/api/tasks',wrap(req=>{const status=req.query.status;if(status&&!['todo','doing','done'].includes(status))throw Error('Invalid status');return db.prepare(`SELECT tasks.*,members.name assignee FROM tasks LEFT JOIN members ON members.id=tasks.assignee_id ${status?'WHERE tasks.status=?':''} ORDER BY tasks.id DESC`).all(...(status?[status]:[]))}));
app.post('/api/tasks',wrap(req=>{const {title,description='',priority='medium',assignee_id=null,due_date=null}=req.body;if(typeof title!=='string'||!title.trim()||title.length>200||
    typeof description!=='string'||description.length>3000||
    !['low','medium','high'].includes(priority)||
    !validISODate(due_date)||
    (assignee_id!==null && (!Number.isSafeInteger(Number(assignee_id))||Number(assignee_id)<1)))
    throw Error('Invalid title, description, priority, assignee, or canonical due date');
 return db.prepare('INSERT INTO tasks(title,description,priority,assignee_id,due_date) VALUES(?,?,?,?,?)')
  .run(title.trim(),description,priority,assignee_id||null,due_date||null)}));
app.patch('/api/tasks/:id',wrap(req=>{const {status,priority}=req.body;if(status&&!['todo','doing','done'].includes(status))throw Error('Invalid status');if(priority&&!['low','medium','high'].includes(priority))throw Error('Invalid priority');const r=db.prepare('UPDATE tasks SET status=COALESCE(?,status),priority=COALESCE(?,priority) WHERE id=?').run(status||null,priority||null,req.params.id);if(!r.changes)throw Error('Task not found');return {updated:true}}));app.delete('/api/tasks/:id',wrap(req=>({deleted:db.prepare('DELETE FROM tasks WHERE id=?').run(req.params.id).changes>0})));
app.get('/api/tasks/:id/history', (req,res)=>{
  const id=Number(req.params.id);
  if(!Number.isSafeInteger(id)||id<1)return res.status(400).json({error:'Invalid ID'});
  const entity=db.prepare('SELECT id FROM tasks WHERE id=?').get(id);
  if(!entity)return res.status(404).json({error:'Not found'});
  const events=db.prepare('SELECT id,previous_value,new_value,changed_at FROM tasks_status_events WHERE entity_id=? ORDER BY id').all(id);
  res.set('Cache-Control','no-store');
  res.json(events);
});

// Safe, read-only CSV export for the local tasks dataset.
app.get('/api/export/tasks.csv', (_req,res)=>{
  try {
    const {serialize}=require('./lib/csv');
    const stmt=db.prepare("SELECT id,title,priority,status,assignee_id,due_date,created_at FROM tasks ORDER BY id");
    const rows=stmt.all();
    const columns=stmt.columns().map(column=>column.name);
    res.set('Content-Type','text/csv; charset=utf-8');
    res.set('Content-Disposition','attachment; filename="tasks.csv"');
    res.set('Cache-Control','no-store');
    res.send(serialize(rows,columns));
  }catch(_error){res.status(500).json({error:'CSV export unavailable'})}
});

// Lightweight service introspection: intentionally no secrets or database contents.
app.get('/api/health',(_req,res)=>{try{db.prepare('SELECT 1').get();res.json({status:'ok',service:process.env.npm_package_name||'portfolio-service'})}catch(_e){res.status(503).json({status:'unavailable'})}});
app.get('/api/workload',(_req,res)=>{
 try {
   const members=db.prepare(`SELECT m.id,m.name,
     COUNT(t.id) AS assigned_tasks,
     COALESCE(SUM(CASE WHEN t.status!='done' THEN 1 ELSE 0 END),0) AS open_tasks,
     COALESCE(SUM(CASE WHEN t.status!='done' AND t.priority='high' THEN 1 ELSE 0 END),0) AS high_priority_tasks,
     COALESCE(SUM(CASE WHEN t.status!='done' AND t.due_date<date('now') THEN 1 ELSE 0 END),0) AS overdue_tasks
     FROM members m LEFT JOIN tasks t ON t.assignee_id=m.id
     GROUP BY m.id ORDER BY m.name`).all();
   const unassigned=db.prepare("SELECT COUNT(*) AS total FROM tasks WHERE assignee_id IS NULL AND status!='done'").get().total;
   res.set('Cache-Control','no-store');
   res.json({members,unassigned_open_tasks:unassigned});
 }catch(_error){res.status(500).json({error:'Unable to load workload'})}
});
app.get('/api/insights',(_req,res)=>{try{res.json((()=>{ const statuses=db.prepare('SELECT status,COUNT(*) count FROM tasks GROUP BY status ORDER BY status').all();const priorities=db.prepare('SELECT priority,COUNT(*) count FROM tasks GROUP BY priority ORDER BY priority').all();const overdue=db.prepare("SELECT COUNT(*) n FROM tasks WHERE status != 'done' AND due_date < date('now')").get().n;return {tasks_by_status:statuses,tasks_by_priority:priorities,overdue_tasks:overdue}; })())}catch(_e){res.status(500).json({error:'Unable to load insights'})}});
app.use((err,req,res,next)=>{if(err&&err.type==='entity.too.large')return res.status(413).json({error:'Request body too large'});if(err instanceof SyntaxError && 'body' in err)return res.status(400).json({error:'Malformed JSON'});return res.status(500).json({error:'Unexpected server error'})});
app.listen(Number(process.env.PORT)||3000);
